// Update the file pattern on a Cronacle FileEventDefinition
void setFilePatternBusinessDate(String eventName,String businessDate) throws Exception
{
    Partition p = jcsSession.getPartitionByName("%Partition%");
    for (Iterator it = p.getEventDefinitionByName(eventName).getFileEventDefinitions(); it.hasNext();)
    {
        FileEventDefinition fed = ((FileEventDefinition)it.next());
        //String pattern = fed.getPattern().replace("20220606",businessDate);
        String pattern = fed.getDescription().replace("20220606",businessDate).replace("yymmdd",businessDate.substring(2,8));
        fed.setPattern(pattern);
        jcsSession.persist();
    }

}

// Update the file pattern on a Cronacle FileEventDefinition
void setFilePatternBusinessDateDelimiter(String eventName,String businessDate,String startDelimeter,String endDelimeter) throws Exception
{
    Partition p = jcsSession.getPartitionByName("%Partition%");
    for (Iterator it = p.getEventDefinitionByName(eventName).getFileEventDefinitions(); it.hasNext();)
    {
        FileEventDefinition fed = ((FileEventDefinition)it.next());
        String pattern = fed.getPattern();
        int u = pattern.indexOf(startDelimeter,3);int a = pattern.indexOf(endDelimeter);

        jcsOut.println(fed.getPattern());
        fed.setPattern(pattern.replace(pattern.substring(u+1,a+1),businessDate+endDelimeter));
        jcsSession.persist();
    }

}


// Extract business date from Cronacle AC_BUSINESSDATE table or use current date
String getBusinessDate() throws Exception
{
   String returnValue = null;

   String sql = "select tv.* from TableValue tv join Table t on tv.Table = t.UniqueId join Partition p on t.Partition = p.UniqueId where t.Name = ? and p.Name = ? and tv.SearchColumnName = ?";

   Iterator it = jcsSession.executeObjectQuery(sql, new Object [] {"AC_BUSINESSDATE","%Partition%","BUSINESSDATE"});
   if (it.hasNext())
   {
     TableValue tv = (TableValue) it.next();
     returnValue = tv.getColumnValue().replace("/","");
   }
   else
   {
     SimpleDateFormat dateFormat = new SimpleDateFormat("20220606");
     returnValue =  dateFormat.format(new GregorianCalendar().getTime());
   }
   return returnValue;
}
